public class Main {
    static long computeArea(int ax1, int ay1, int ax2, int ay2, int bx1, int by1, int bx2, int by2) {
        long area1 = (long)(ax2 - ax1) * (ay2 - ay1);
        long area2 = (long)(bx2 - bx1) * (by2 - by1);
        long overlapX = Math.max(0, Math.min(ax2, bx2) - Math.max(ax1, bx1));   // 0 if no true overlap
        long overlapY = Math.max(0, Math.min(ay2, by2) - Math.max(ay1, by1));   // 0 if no true overlap
        return area1 + area2 - overlapX * overlapY;                                // inclusion-exclusion
    }
}

