long long computeArea(int ax1, int ay1, int ax2, int ay2, int bx1, int by1, int bx2, int by2) {
    long long area1 = (long long)(ax2 - ax1) * (ay2 - ay1);
    long long area2 = (long long)(bx2 - bx1) * (by2 - by1);
    long long overlapX = max(0, min(ax2, bx2) - max(ax1, bx1));   // 0 if no true overlap
    long long overlapY = max(0, min(ay2, by2) - max(ay1, by1));   // 0 if no true overlap
    return area1 + area2 - overlapX * overlapY;                       // inclusion-exclusion
}
